//! WP-A3 rows of the native-seam table (WP-A core API, `wp-a-core/API.md`). Generated by
//! `refactor/wp-a23-tools/gen_rows_rs.py` from `refactor/wp-a3/data/rows.tsv`: 64-byte guards from the
//! owned 13.0.5 main ELF (sha256 0789f0a4ae9652f335eca5eabc7df3e58b0954012a0bebdea374f317706536c2), placement
//! audit and card scan per seam (`data/AUDIT.md`). Do not edit by hand; regenerate.
use super::*;

#[rustfmt::skip]
pub const ROWS: &[Seam] = &include!(concat!(env!("OUT_DIR"), "/tables/rows_a3.ROWS.rs"));

/// Ratchet (API.md): `path:fn` of every `#[skyline::hook]` in WP-A3's files without a row yet. Empty: the three
/// `lua2cpp_common` hooks are image rows in `images.rs` (rows 27/36).
#[cfg(test)]
pub const UNCONVERTED: &[&str] = &[];

#[cfg(test)]
mod tests {
    lib_unit_tests! {
    use super::*;

    fn wp_a3_labels_are_unique_and_prefixed_by_their_group_or_needle() {
        for (i, a) in ROWS.iter().enumerate() {
            assert!(a.label.starts_with(&format!("{}.", a.group)) || a.label.starts_with("needle."), "{}", a.label);
            assert!(ROWS[i + 1..].iter().all(|b| b.label != a.label), "duplicate {}", a.label);
        }
    }

    fn wp_a3_has_one_hook_row_per_offset_and_justifies_entry_hooks() {
        let hooks: Vec<&Seam> = ROWS.iter().filter(|s| matches!(s.kind, SeamKind::Hook { .. })).collect();
        for (i, a) in hooks.iter().enumerate() {
            assert!(hooks[i + 1..].iter().all(|b| b.offset != a.offset), "two hook rows at {:#x}", a.offset);
            if matches!(a.kind, SeamKind::Hook { placement: Placement::Entry, .. }) {
                assert!(!a.note.is_empty(), "entry hook {} without a justification", a.label);
            }
        }
    }

    fn wp_a3_guards_are_64_owned_bytes_and_offsets_are_in_main() {
        for s in ROWS {
            assert!(s.guard.iter().any(|b| *b != 0), "{}", s.label);
            assert!(s.offset < 0x52aa000, "{} outside main's image", s.label);
        }
    }

    fn slot(label: &str) -> u64 {
        let row = ROWS.iter().find(|s| s.label == label).expect(label);
        assert!(matches!(row.kind, SeamKind::Hook { form: HookForm::VtableSlot, .. }));
        assert!(row.guard[8..].iter().all(|b| *b == 0));
        let mut target = [0u8; 8];
        target.copy_from_slice(&row.guard[..8]);
        u64::from_le_bytes(target)
    }

    fn wp_a3_vtable_slot_rows_encode_the_original_targets() {
        assert_eq!(slot("training.vtable_on_init_slot"), 0x60dfa0);
        assert_eq!(slot("training.vtable_on_frame_slot"), 0x614630);
    }

    /// rc.9: this module's cases in one table. Each case runs on its own thread, as the test harness ran it.
    #[test]
    fn case_table() {
        crate::test_table::run(&[
            ("wp_a3_labels_are_unique_and_prefixed_by_their_group_or_needle", wp_a3_labels_are_unique_and_prefixed_by_their_group_or_needle as fn()),
            ("wp_a3_has_one_hook_row_per_offset_and_justifies_entry_hooks", wp_a3_has_one_hook_row_per_offset_and_justifies_entry_hooks as fn()),
            ("wp_a3_guards_are_64_owned_bytes_and_offsets_are_in_main", wp_a3_guards_are_64_owned_bytes_and_offsets_are_in_main as fn()),
            ("wp_a3_vtable_slot_rows_encode_the_original_targets", wp_a3_vtable_slot_rows_encode_the_original_targets as fn()),
        ]);
    }
    }
}
